import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  Card,
  CircularProgress,
  Dialog,
  DialogContent,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from "@mui/material";

import Autocomplete from "@mui/material/Autocomplete";
import { toast } from "react-toastify";

import { usePpiBankTransfer } from "./BankTransferPPIProvider";
import {
  getPpiBankList,
  addPpiBeneficiary,
  verifyPpiBeneficiary,
  verificationBank,
  settingBank,
} from "../../api/login/Login";
import PpiPageLayout from "./PpiPageLayout";

const PpiAddBeneficiary = () => {
  const { setCurrentPage, setGlobalLoader, setBeneficiaryList, walletCall } = usePpiBankTransfer();
  const [btnLoading, setBtnLoading] = useState(false);
  const [directLoading, setDirectLoading] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [isVerified, setIsVerified] = useState(false);
  const [verificationCharge, setVerificationCharge] = useState("");
  const [selectedBank, setSelectedBank] = useState(null);

  const [bankList, setBankList] = useState([]);
  const [mobile, setMobile] = useState("");
  const [showOtpModal, setShowOtpModal] = useState(false);
  const [location, setLocation] = useState({
    latitude: "",
    longitude: "",
  });

  const [otp, setOtp] = useState("");

  useEffect(() => {
    const savedMobile = localStorage.getItem("mobile")?.slice(-10);
    if (savedMobile) setMobile(savedMobile);
  }, []);

  useEffect(() => {
    const fetchCharge = async () => {
      try {
        const res = await settingBank();
        const charge = res?.data?.data?.bankVerificationCharge;
        if (charge !== undefined) setVerificationCharge(charge);
      } catch (e) {
        // Fallback silently if settings endpoint not accessible
      }
    };
    fetchCharge();
  }, []);

  useEffect(() => {
    if (!navigator.geolocation) {
      toast.error("Geolocation is not supported by this browser");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setLocation({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
        });
      },
      (error) => {
        toast.error("Please allow location access");
        console.error(error);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0,
      },
    );
  }, []);

  const [form, setForm] = useState({
    name: "",
    accountNumber: "",
    ifsc: "",
    bankId: "",
  });

  const fetchBankList = async () => {
    try {
      const res = await getPpiBankList();
      const list = (res?.data?.data || []).filter((b) => {
        const name = (b?.bank_name || "").toLowerCase().trim();
        return name && !name.includes("unibcomp") && b?.bankID;
      });
      const sorted = [...list].sort((a, b) =>
        (a.bank_name || "").localeCompare(b.bank_name || "", undefined, {
          sensitivity: "base",
        })
      );
      setBankList(sorted);
    } catch {
      toast.error("Bank List Load Failed");
    }
  };

  useEffect(() => {
    fetchBankList();
  }, []);

  // Smart filter function: ensures alphabetical order and prioritizes exact/prefix matches
  const filterBankOptions = (options, { inputValue }) => {
    const query = (inputValue || "").trim().toLowerCase();
    if (!query) {
      return options;
    }

    const escapedQuery = query.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");
    const wordBoundaryRegex = new RegExp(`(^|\\s)${escapedQuery}`, "i");

    // Match banks by name or ifsc
    const matches = options.filter((option) => {
      const name = (option.bank_name || "").toLowerCase();
      const ifsc = (option.ifsc_code || "").toLowerCase();
      return name.includes(query) || ifsc.includes(query);
    });

    return matches.sort((a, b) => {
      const nameA = (a.bank_name || "").toLowerCase();
      const nameB = (b.bank_name || "").toLowerCase();

      // 1. Exact name match
      const exactA = nameA === query;
      const exactB = nameB === query;
      if (exactA && !exactB) return -1;
      if (!exactA && exactB) return 1;

      // 2. Starts with query (e.g. typing "cen" matches "CENTRAL BANK OF INDIA")
      const startsA = nameA.startsWith(query);
      const startsB = nameB.startsWith(query);
      if (startsA && !startsB) return -1;
      if (!startsA && startsB) return 1;

      // 3. Word starts with query (word-boundary match)
      const wordA = wordBoundaryRegex.test(nameA);
      const wordB = wordBoundaryRegex.test(nameB);
      if (wordA && !wordB) return -1;
      if (!wordA && wordB) return 1;

      // 4. Alphabetical tie-break
      return (a.bank_name || "").localeCompare(b.bank_name || "", undefined, {
        sensitivity: "base",
      });
    });
  };

  // Bank Verification (Penny Drop auto-fetch name)
  const handleVerifyAccount = async () => {
    if (!form.accountNumber) {
      toast.error("Please enter Account Number first");
      return;
    }
    if (!form.ifsc || !form.bankId) {
      toast.error("Please select a Bank first");
      return;
    }

    setVerifying(true);
    try {
      const res = await verificationBank({
        account_number: form.accountNumber,
        bankAccount: form.accountNumber,
        ifsc: form.ifsc,
        bank_name: selectedBank?.bank_name || "",
        phone: mobile,
        name: form.name || "Customer",
      });

      const data = res?.data;
      const isSuccess =
        data?.statusCode === "200" ||
        data?.status_Code === "200" ||
        data?.statusCode === 200 ||
        (!data?.error && data?.data?.bank_account_name);

      if (isSuccess) {
        const verifiedName = data?.data?.bank_account_name || "";
        if (verifiedName) {
          setForm((prev) => ({
            ...prev,
            name: verifiedName,
          }));
        }
        setIsVerified(true);
        if (typeof walletCall === "function") {
          walletCall();
        }
        toast.success(data?.message || "Bank Account Verified Successfully!");
      } else {
        setIsVerified(false);
        toast.error(data?.message || "Account verification failed");
      }
    } catch (err) {
      setIsVerified(false);
      const msg =
        err?.response?.data?.message ||
        err?.message ||
        "Account verification failed";
      toast.error(msg);
    } finally {
      setVerifying(false);
    }
  };

  const handleSubmit = async () => {
    if (!form.name || !form.accountNumber || !form.ifsc || !form.bankId) {
      toast.error("All fields are required");
      return;
    }

    const payload = {
      name: form.name,
      accountNumber: form.accountNumber,
      ifsc: form.ifsc,
      bankId: form.bankId,
      mobile,
    };

    setBtnLoading(true);
    setGlobalLoader(true);

    try {
      const res = await addPpiBeneficiary(payload);
      const data = res?.data?.data;

      if (data?.statuscode === "OTP") {
        toast.success("OTP sent to registered mobile");
        setShowOtpModal(true);
      } else if (data?.statuscode === "TXN") {
        toast.success("Beneficiary Added Successfully!");
        setCurrentPage("ppi-status-page");
      } else {
        toast.error(data?.status || "Failed to add beneficiary");
      }
    } catch (err) {
      toast.error("Failed to add beneficiary");
    } finally {
      setBtnLoading(false);
      setGlobalLoader(false);
    }
  };

  // Direct Add (Bypasses Instantpay API completely - NO OTP generated or sent to mobile)
  const handleDirectAdd = async () => {
    if (!form.name || !form.accountNumber || !form.ifsc || !form.bankId) {
      toast.error("All fields are required");
      return;
    }

    setDirectLoading(true);
    setGlobalLoader(true);

    try {
      const cleanAccount = String(form.accountNumber).trim();
      const newBen = {
        id: "DIR_" + Date.now(),
        name: form.name.trim(),
        account: cleanAccount,
        ifsc: form.ifsc.trim().toUpperCase(),
        bank: selectedBank?.bank_name || form.ifsc,
        bankId: form.bankId,
        bankStatus: "REGISTERED",
        isDirect: true,
      };

      // 1. Tell local backend to save directly in DB without calling Instantpay (Zero OTP!)
      try {
        await addPpiBeneficiary({
          name: newBen.name,
          accountNumber: newBen.account,
          ifsc: newBen.ifsc,
          bankId: newBen.bankId,
          bankName: newBen.bank,
          mobile,
          isDirect: true,
        });
      } catch (backendErr) {
        console.warn("Direct add local backend note:", backendErr);
      }

      // 2. Save directly into localStorage for this customer mobile
      try {
        const storageKey = `ppi_direct_bens_${mobile || "default"}`;
        const existingRaw = localStorage.getItem(storageKey);
        const existingList = existingRaw ? JSON.parse(existingRaw) : [];
        const filteredList = existingList.filter(
          (b) => String(b.account) !== cleanAccount
        );
        localStorage.setItem(
          storageKey,
          JSON.stringify([newBen, ...filteredList])
        );
      } catch (storageErr) {
        console.warn("Could not save to localStorage:", storageErr);
      }

      // 3. Update context beneficiary list
      if (typeof setBeneficiaryList === "function") {
        setBeneficiaryList((prev) => {
          const list = Array.isArray(prev?.beneficiaries)
            ? prev.beneficiaries
            : [];
          const filtered = list.filter(
            (b) => String(b.account) !== cleanAccount
          );
          return {
            ...(prev || {}),
            beneficiaries: [newBen, ...filtered],
          };
        });
      }

      toast.success("Beneficiary Added Successfully (Direct)!");
      setCurrentPage("ppi-send-money");
    } catch (err) {
      toast.error("Failed to add beneficiary");
    } finally {
      setDirectLoading(false);
      setGlobalLoader(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (!otp || otp.length !== 6) {
      toast.error("Enter valid 6 digit OTP");
      return;
    }

    setBtnLoading(true);
    setGlobalLoader(true);

    try {
      const res = await verifyPpiBeneficiary({
        mobile,
        otp,
        latitude: location.latitude,
        longitude: location.longitude,
      });

      const data = res?.data?.data;

      if (data?.statuscode === "TXN") {
        toast.success("Beneficiary Verified Successfully");
        setShowOtpModal(false);
        setOtp("");
        if (typeof walletCall === "function") {
          walletCall();
        }
        setCurrentPage("ppi-status-page");
      } else {
        toast.error(data?.status || "OTP verification failed");
      }
    } catch (err) {
      toast.error(
        err?.response?.data?.message ||
          err?.message ||
          "OTP verification failed"
      );
    } finally {
      setBtnLoading(false);
      setGlobalLoader(false);
    }
  };

  const inputSx = {
    "& .MuiOutlinedInput-root": {
      borderRadius: "12px",
      backgroundColor: "#deecff",
    },
    "& .MuiOutlinedInput-notchedOutline": {
      borderColor: "#90a7c4",
    },
    "&:hover .MuiOutlinedInput-notchedOutline": {
      borderColor: "#193968",
    },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
      borderColor: "#193968",
    },
  };

  const disabledInputSx = {
    "& .MuiOutlinedInput-root": {
      borderRadius: "12px",
      backgroundColor: "#f8fafc",
    },
    "& .MuiInputBase-input.Mui-disabled": {
      WebkitTextFillColor: "#334155",
      fontWeight: 500,
    },
  };

  return (
    <PpiPageLayout title="Add Beneficiary">
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          py: { xs: 1, sm: 2 },
        }}
      >
        <Card
          sx={{
            p: { xs: 2.5, sm: 3.5 },
            borderRadius: "22px",
            background: "linear-gradient(145deg,#ffffff,#f8faff)",
            boxShadow: "0 10px 30px rgba(15, 23, 42, 0.08)",
            maxWidth: { xs: "100%", sm: 660 },
            width: "100%",
            border: "1px solid rgba(226, 232, 240, 0.8)",
          }}
        >
          <Grid container spacing={1.8}>
            {/* REGISTERED MOBILE */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Registered Mobile Number"
                value={mobile}
                disabled
                sx={disabledInputSx}
                className="mui-autofill-fix"
              />
            </Grid>

            {/* BENEFICIARY NAME */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Beneficiary Name"
                name="name"
                sx={inputSx}
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                className="mui-autofill-fix"
                InputProps={{
                  endAdornment: isVerified ? (
                    <InputAdornment position="end">
                      <span
                        style={{
                          color: "#0d8a4e",
                          fontWeight: 700,
                          fontSize: "11px",
                          backgroundColor: "rgba(13, 138, 78, 0.12)",
                          padding: "2px 6px",
                          borderRadius: "4px",
                        }}
                      >
                        ✓ Verified
                      </span>
                    </InputAdornment>
                  ) : null,
                }}
                helperText={
                  isVerified ? (
                    <span
                      style={{
                        color: "#0d8a4e",
                        fontWeight: 600,
                        fontSize: "11px",
                      }}
                    >
                      ✓ Bank Verified: {form.name}
                    </span>
                  ) : (
                    <span style={{ fontSize: "11px", color: "#64748b" }}>
                      Type manually or use 'Verify Account'
                    </span>
                  )
                }
              />
            </Grid>

            {/* SEARCH BANK */}
            <Grid item xs={12} sm={6}>
              <Autocomplete
                fullWidth
                size="small"
                options={bankList}
                filterOptions={filterBankOptions}
                value={selectedBank}
                getOptionLabel={(option) => option.bank_name || ""}
                isOptionEqualToValue={(option, val) =>
                  option?.bankID === val?.bankID || option?._id === val?._id
                }
                onChange={(e, selected) => {
                  setSelectedBank(selected);
                  setForm((prev) => ({
                    ...prev,
                    bankId: selected?.bankID || "",
                    ifsc: selected?.ifsc_code || "",
                  }));
                  setIsVerified(false);
                }}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    label="Search Bank"
                    className="mui-autofill-fix"
                    sx={{
                      background: "#fbfcfd",
                      "& .MuiOutlinedInput-root": {
                        borderRadius: "12px",
                      },
                      "& .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#90a7c4",
                      },
                      "&:hover .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#193968",
                      },
                      "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                        borderColor: "#193968",
                      },
                    }}
                  />
                )}
                className="mui-autofill-fix"
              />
            </Grid>

            {/* IFSC CODE */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="IFSC Code"
                name="ifsc"
                sx={disabledInputSx}
                value={form.ifsc}
                disabled
              />
            </Grid>

            {/* ACCOUNT NUMBER */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Account Number"
                name="accountNumber"
                sx={inputSx}
                value={form.accountNumber}
                onChange={(e) => {
                  setForm({
                    ...form,
                    accountNumber: e.target.value.replace(/\s+/g, ""),
                  });
                  setIsVerified(false);
                }}
                className="mui-autofill-fix"
              />
            </Grid>

            {/* VERIFY ACCOUNT BUTTON */}
            <Grid item xs={12} sm={6}>
              <Button
                fullWidth
                variant="outlined"
                disabled={
                  verifying ||
                  isVerified ||
                  !form.accountNumber ||
                  !form.ifsc ||
                  !form.bankId
                }
                onClick={handleVerifyAccount}
                sx={{
                  height: "40px",
                  borderRadius: "50px",
                  fontWeight: 700,
                  fontSize: "13px",
                  borderColor: isVerified ? "#0d8a4e" : "#193968",
                  color: isVerified ? "#0d8a4e" : "#193968",
                  backgroundColor: isVerified
                    ? "rgba(13, 138, 78, 0.08)"
                    : "transparent",
                  "&:hover": {
                    borderColor: isVerified ? "#0d8a4e" : "#152c56",
                    backgroundColor: isVerified
                      ? "rgba(13, 138, 78, 0.12)"
                      : "rgba(25, 57, 104, 0.04)",
                  },
                }}
              >
                {verifying ? (
                  <CircularProgress size={18} sx={{ color: "#193968" }} />
                ) : isVerified ? (
                  "✓ Account Verified"
                ) : (
                  `Verify Account ${
                    verificationCharge ? `(₹${verificationCharge})` : ""
                  }`
                )}
              </Button>
              <Typography
                variant="caption"
                sx={{
                  display: "block",
                  textAlign: "center",
                  color: "#667085",
                  fontSize: "10.5px",
                  mt: 0.5,
                  lineHeight: 1.2,
                }}
              >
                {isVerified
                  ? "✓ Account verified with bank."
                  : "💡 Optional: Auto-verify name with bank."}
              </Typography>
            </Grid>

            {/* ACTION BUTTONS */}
            <Grid item xs={12} sx={{ mt: 1 }}>
              <Box display="flex" gap={1.5} flexDirection={{ xs: "column", sm: "row" }}>
                {/* 1. Add with OTP */}
                <Button
                  fullWidth
                  variant="contained"
                  disabled={btnLoading || directLoading}
                  onClick={handleSubmit}
                  sx={{
                    py: 1.1,
                    borderRadius: "50px",
                    fontWeight: 700,
                    fontSize: "14px",
                    backgroundColor: "#193968",
                    color: "#fff",
                    whiteSpace: "nowrap",
                    "&:hover": { backgroundColor: "#152c56" },
                  }}
                >
                  {btnLoading
                    ? "Processing..."
                    : `Add with OTP ${verificationCharge ? `(₹${verificationCharge})` : "(₹3)"}`}
                </Button>

                {/* 2. Direct Add (without verify) */}
                <Button
                  fullWidth
                  variant="contained"
                  disabled={btnLoading || directLoading}
                  onClick={handleDirectAdd}
                  sx={{
                    py: 1.1,
                    borderRadius: "50px",
                    fontWeight: 700,
                    fontSize: "14px",
                    backgroundColor: "#16a34a",
                    color: "#fff",
                    whiteSpace: "nowrap",
                    "&:hover": { backgroundColor: "#15803d" },
                  }}
                >
                  {directLoading ? "Saving..." : "Direct Add"}
                </Button>

                {/* 3. Cancel */}
                <Button
                  variant="outlined"
                  disabled={btnLoading || directLoading}
                  onClick={() => setCurrentPage("ppi-send-money")}
                  sx={{
                    minWidth: "110px",
                    borderRadius: "50px",
                    color: "#193968",
                    borderColor: "#cbd5e1",
                    fontWeight: 600,
                    fontSize: "14px",
                    "&:hover": {
                      borderColor: "#94a3b8",
                      backgroundColor: "#f8fafc",
                    },
                  }}
                >
                  Cancel
                </Button>
              </Box>
            </Grid>
          </Grid>
        </Card>
      </Box>
      <Dialog
        open={showOtpModal}
        onClose={() => {
          setShowOtpModal(false);
          setOtp("");
        }}
        fullWidth
        maxWidth="xs"
        PaperProps={{
          sx: {
            borderRadius: "20px",
            background: "linear-gradient(145deg,#ffffff,#f5f7fc)",
          },
        }}
      >
        <DialogContent sx={{ p: 3 }}>
          <Typography
            fontSize="18px"
            fontWeight={700}
            textAlign="center"
            sx={{ color: "#193968", mb: 2 }}
          >
            Verify OTP
          </Typography>

          <TextField
            fullWidth
            autoFocus
            className="mui-autofill-fix"
            label="6 Digit OTP"
            value={otp}
            inputProps={{
              maxLength: 6,
              style: {
                letterSpacing: "4px",
                textAlign: "center",
                fontSize: "18px",
                fontWeight: 600,
              },
            }}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, ""))}
            sx={inputSx}
          />

          <Button
            fullWidth
            disabled={btnLoading}
            onClick={handleVerifyOtp}
            sx={{
              mt: 3,
              py: 1.4,
              borderRadius: "50px",
              fontWeight: 700,
              backgroundColor: "#193968",
              color: "#fff",
            }}
          >
            {btnLoading ? "Verifying..." : "Verify OTP"}
          </Button>

          <Button
            fullWidth
            sx={{
              mt: 1.5,
              borderRadius: "50px",
              color: "#193968",
              fontWeight: 600,
            }}
            onClick={() => {
              setShowOtpModal(false);
              setOtp("");
            }}
          >
            Cancel
          </Button>
        </DialogContent>
      </Dialog>
    </PpiPageLayout>
  );
};

export default PpiAddBeneficiary;
