import React, { useState, useEffect } from "react";
import {
  Box,
  Card,
  Typography,
  Button,
  Dialog,
  DialogContent,
  TextField,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  CircularProgress,
  Grid,
  Divider,
  useMediaQuery,
  Radio,
  RadioGroup,
  FormControlLabel,
} from "@mui/material";
import SecurityIcon from "@mui/icons-material/Security";
import PersonRemoveIcon from "@mui/icons-material/PersonRemove";
import BlockIcon from "@mui/icons-material/Block";
import WarningAmberIcon from "@mui/icons-material/WarningAmber";
import { toast } from "react-toastify";
import { usePpiBankTransfer } from "./BankTransferPPIProvider";
import {
  generateTransactionOtp,
  ppiTransaction,
  deletePpiBeneficiary,
  deletePpiBeneficiaryVerify,
  delinkPpiRemitter,
} from "../../api/login/Login";
import PpiPageLayout from "./PpiPageLayout";

const PpiSendMoney = () => {
  const { beneficiaryList, setCurrentPage, setBeneficiaryList } = usePpiBankTransfer();
  const remitter = beneficiaryList;
  const [directBens, setDirectBens] = useState([]);

  const [openPopup, setOpenPopup] = useState(false);
  const [openDeletePopup, setOpenDeletePopup] = useState(false);
  const [selectedBen, setSelectedBen] = useState(null);
  const [showOtpField, setShowOtpField] = useState(false);
  const isMobile = useMediaQuery("(max-width:600px)");

  const [location, setLocation] = useState({ latitude: "0", longitude: "0" });
  const [form, setForm] = useState({
    transferMode: "IMPS",
    transferAmount: "",
    otp: "",
  });
  const [mobile, setMobile] = useState("");
  const [deleteOtp, setDeleteOtp] = useState("");
  const [btnLoading, setBtnLoading] = useState(false);

  // Safety Pull-Out State
  const [safetyMenuAnchor, setSafetyMenuAnchor] = useState(null);
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [actionType, setActionType] = useState("delink");
  const [delinkLoading, setDelinkLoading] = useState(false);

  const handleOpenSafetyMenu = (e) => setSafetyMenuAnchor(e.currentTarget);
  const handleCloseSafetyMenu = () => setSafetyMenuAnchor(null);

  const handleTriggerSafetyAction = (type) => {
    setActionType(type);
    handleCloseSafetyMenu();
    setConfirmDialogOpen(true);
  };

  const handleConfirmDelink = async () => {
    if (delinkLoading) return;
    setDelinkLoading(true);
    try {
      const res = await delinkPpiRemitter({
        mobile,
        disableService: actionType === "disable",
      });
      if (res?.data?.status) {
        toast.success(res.data.message || "Remitter de-linked successfully");
        localStorage.removeItem("mobile");
        setConfirmDialogOpen(false);
        if (actionType === "disable") {
          window.location.href = "/dashboard";
        } else {
          setCurrentPage("ppi-status-page");
        }
      } else {
        toast.error(res?.data?.message || "Failed to de-link remitter");
      }
    } catch (err) {
      toast.error(err?.response?.data?.message || "Error while de-linking remitter");
    } finally {
      setDelinkLoading(false);
    }
  };

  useEffect(() => {
    const savedMobile = localStorage.getItem("mobile")?.slice(-10);
    if (savedMobile) {
      setMobile(savedMobile);
      try {
        const raw = localStorage.getItem(`ppi_direct_bens_${savedMobile}`);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) setDirectBens(parsed);
        }
      } catch (e) {
        console.warn(e);
      }
    }
  }, []);

  // Combine beneficiaries from API + localStorage direct additions
  const beneficiaries = React.useMemo(() => {
    const apiBens = Array.isArray(beneficiaryList?.beneficiaries)
      ? [...beneficiaryList.beneficiaries]
      : [];

    const existingAccounts = new Set(apiBens.map((b) => String(b.account)));
    const merged = [...apiBens];

    for (const db of directBens) {
      if (!existingAccounts.has(String(db.account))) {
        merged.unshift(db);
        existingAccounts.add(String(db.account));
      }
    }
    return merged;
  }, [beneficiaryList, directBens]);

  useEffect(() => {
    navigator.geolocation?.getCurrentPosition(
      (pos) =>
        setLocation({
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
        }),
      () => toast.warning("Location Disabled, Using Default"),
    );
  }, []);

  const handleOpenPopup = (ben) => {
    setSelectedBen(ben);
    setOpenPopup(true);
    setShowOtpField(false);
    setForm({ transferMode: "IMPS", transferAmount: "", otp: "" });
  };

  const handleSendOtp = async () => {
    if (btnLoading) return;

    if (!form.transferMode || !form.transferAmount)
      return toast.error("Enter Transfer Mode & Amount");

    if (mobile.length !== 10) return toast.error("Invalid mobile number");

    setBtnLoading(true);

    try {
      const res = await generateTransactionOtp({
        beneficiaryId: selectedBen.id,
        beneficiary_name: selectedBen.name,
        bank_name: selectedBen.bank,
        accountNumber: selectedBen.account,
        ifsc: selectedBen.ifsc,
        transferMode: form.transferMode,
        amount: form.transferAmount,
        mobile,
        latitude: location.latitude,
        longitude: location.longitude,
      });

      const statusCode = res?.data?.data?.statuscode;

      if (statusCode === "OTP") {
        toast.success("OTP Sent Successfully");
        setShowOtpField(true);
      } else if (statusCode === "IST") {
        toast.error(res?.data?.data?.status || "Session expired");
        localStorage.removeItem("mobile");
        setCurrentPage("ppi-status-page");
      } else {
        toast.error(res?.data?.data?.status || "Failed to send OTP");
      }
    } catch {
      toast.error("Something went wrong");
    } finally {
      setBtnLoading(false);
    }
  };

  const handleConfirmPayment = async () => {
    if (btnLoading) return;
    if (!form.otp) return toast.error("Enter OTP");

    setBtnLoading(true);

    try {
      const res = await ppiTransaction({
        beneficiaryId: selectedBen.id,
        beneficiary_name: selectedBen.name,
        bank_name: selectedBen.bank,
        accountNumber: selectedBen.account,
        ifsc: selectedBen.ifsc,
        transferMode: form.transferMode,
        amount: form.transferAmount,
        otp: form.otp,
        mobile,
        latitude: location.latitude,
        longitude: location.longitude,
      });

      const api = res?.data;

      if (api?.status === true) {
        toast.success(api?.message || "Transaction Success");
        setOpenPopup(false);
      } else {
        toast.error(api?.message || "Transaction Failed");
      }
    } catch (error) {
      toast.error(error?.response?.data?.message || "Something went wrong");
    } finally {
      setBtnLoading(false);
    }
  };

  const handleDeleteBeneficiary = async (ben) => {
    if (btnLoading) return;

    // 1. Direct Add beneficiary - remove locally without any Instantpay API or OTP
    if (ben?.isDirect || String(ben?.id).startsWith("DIR_")) {
      try {
        const savedMobile = mobile || localStorage.getItem("mobile")?.slice(-10);
        const storageKey = `ppi_direct_bens_${savedMobile || "default"}`;
        const raw = localStorage.getItem(storageKey);
        if (raw) {
          const parsed = JSON.parse(raw);
          const filtered = parsed.filter(
            (b) => String(b.account) !== String(ben.account)
          );
          localStorage.setItem(storageKey, JSON.stringify(filtered));
          setDirectBens(filtered);
        }
        if (typeof setBeneficiaryList === "function") {
          setBeneficiaryList((prev) => ({
            ...(prev || {}),
            beneficiaries: (prev?.beneficiaries || []).filter(
              (b) => String(b.account) !== String(ben.account)
            ),
          }));
        }
        toast.success("Beneficiary removed successfully");
      } catch (e) {
        toast.error("Failed to remove beneficiary");
      }
      return;
    }

    // 2. Unregistered/unverified Instantpay card - dismiss from view
    if (ben?.bankStatus === "UNREGISTERED") {
      if (typeof setBeneficiaryList === "function") {
        setBeneficiaryList((prev) => ({
          ...(prev || {}),
          beneficiaries: (prev?.beneficiaries || []).filter(
            (b) =>
              String(b.id) !== String(ben.id) &&
              String(b.account) !== String(ben.account)
          ),
        }));
      }
      toast.success("Unregistered card removed from list");
      return;
    }

    setSelectedBen(ben);
    setBtnLoading(true);

    try {
      const res = await deletePpiBeneficiary({
        beneficiaryId: ben?.id,
        mobile,
      });

      const apiData = res?.data?.data;
      const statusCode = apiData?.statuscode;

      if (statusCode === "OTP") {
        toast.success("OTP Sent for Delete Verification");
        setOpenDeletePopup(true);
      } else {
        toast.error(apiData?.status || "Failed to send delete OTP");
      }
    } catch {
      toast.error("Delete request failed");
    } finally {
      setBtnLoading(false);
    }
  };

  const handleDeleteBeneficiaryVerify = async () => {
    if (btnLoading) return;
    if (!deleteOtp) return toast.error("Enter OTP");

    setBtnLoading(true);

    try {
      const res = await deletePpiBeneficiaryVerify({
        beneficiaryId: selectedBen?.id,
        otp: deleteOtp,
        mobile,
      });

      const api = res?.data?.data;
      const statusCode = api?.statuscode;

      if (statusCode === "TXN") {
        toast.success("Beneficiary Removed Successfully");
        setDeleteOtp("");
        setOpenDeletePopup(false);
        setCurrentPage("ppi-status-page");
      } else if (statusCode === "IST") {
        toast.error(api?.status || "Invalid or expired session token");
        localStorage.removeItem("mobile");
        setDeleteOtp("");
        setOpenDeletePopup(false);
        setCurrentPage("ppi-status-page");
      } else {
        toast.error(api?.status || "Delete failed");
      }
    } catch {
      toast.error("Invalid OTP");
    } finally {
      setBtnLoading(false);
    }
  };
  const inputSx = {
    "& .MuiOutlinedInput-root": {
      borderRadius: "12px",
      backgroundColor: "#deecff",
    },
  };

  const disabledInputSx = {
    "& .MuiOutlinedInput-root": {
      borderRadius: "12px",
      backgroundColor: "#f8fafc",
    },
    "& .MuiInputBase-input.Mui-disabled": {
      WebkitTextFillColor: "#334155",
      fontWeight: 500,
    },
  };

  return (
    <PpiPageLayout title="Send Money">
      <Card
        sx={{
          p: { xs: 2.5, sm: 3 },
          mb: 3,
          borderRadius: "20px",
          background: "linear-gradient(135deg,#ffffff,#f8f9fb)",
          boxShadow: "0 6px 20px rgba(0,0,0,0.06)",
        }}
      >
        <Box display="flex" justifyContent="space-between" alignItems="center" flexWrap="wrap" gap={1}>
          <Typography fontWeight={700} fontSize={{ xs: 18, sm: 20 }}>
            Remitter Details
          </Typography>
          {/* --- UNCOMMENT WHEN READY TO USE SAFETY PULL-OUT --- */}
          {/* <Button
            size="small"
            variant="outlined"
            onClick={handleOpenSafetyMenu}
            startIcon={<SecurityIcon sx={{ fontSize: "16px !important" }} />}
            sx={{
              borderRadius: "20px",
              textTransform: "none",
              fontSize: "13px",
              fontWeight: 600,
              color: "#dc2626",
              borderColor: "#fecaca",
              backgroundColor: "#fef2f2",
              px: 1.8,
              py: 0.5,
              "&:hover": {
                borderColor: "#f87171",
                backgroundColor: "#fee2e2",
              },
            }}
          >
            Safety Options ▾
          </Button>
          <Menu
            anchorEl={safetyMenuAnchor}
            open={Boolean(safetyMenuAnchor)}
            onClose={handleCloseSafetyMenu}
            PaperProps={{
              sx: {
                borderRadius: "14px",
                boxShadow: "0 10px 28px rgba(0,0,0,0.12)",
                minWidth: 250,
                mt: 1,
              },
            }}
          >
            <MenuItem onClick={() => handleTriggerSafetyAction("delink")} sx={{ py: 1.2 }}>
              <ListItemIcon sx={{ color: "#dc2626", minWidth: 36 }}>
                <PersonRemoveIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText
                primary="De-link Remitter Profile"
                secondary="Wipe personal details from portal"
                primaryTypographyProps={{ fontSize: 13.5, fontWeight: 600, color: "#dc2626" }}
                secondaryTypographyProps={{ fontSize: 11, color: "#64748b" }}
              />
            </MenuItem>
            <Divider sx={{ my: 0.5 }} />
            <MenuItem onClick={() => handleTriggerSafetyAction("disable")} sx={{ py: 1.2 }}>
              <ListItemIcon sx={{ color: "#991b1b", minWidth: 36 }}>
                <BlockIcon fontSize="small" />
              </ListItemIcon>
              <ListItemText
                primary="Disable PPI Service"
                secondary="De-link & turn off PPI module"
                primaryTypographyProps={{ fontSize: 13.5, fontWeight: 600, color: "#991b1b" }}
                secondaryTypographyProps={{ fontSize: 11, color: "#64748b" }}
              />
            </MenuItem>
          </Menu> */}
        </Box>

        <Divider sx={{ my: 1, borderColor: "#e5e9f2" }} />

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <Typography fontSize={{ xs: 14, sm: 15 }}>
              <b>Name:</b> {remitter?.firstName} {remitter?.lastName}
            </Typography>
            <Typography fontSize={{ xs: 14, sm: 15 }}>
              <b>Mobile:</b> {mobile}
            </Typography>
          </Grid>
          <Grid item xs={12} sm={6}>
            <Typography fontSize={{ xs: 14, sm: 15 }}>
              <b>Total Limit:</b> ₹{remitter?.limitTotal}
            </Typography>
            <Typography fontSize={{ xs: 14, sm: 15 }}>
              <b>Available:</b> ₹{remitter?.limitAvailable}
            </Typography>
            <Typography fontSize={{ xs: 14, sm: 15 }}>
              <b>Used:</b> ₹{remitter?.limitConsumed}
            </Typography>
          </Grid>
        </Grid>
      </Card>
      <Box display="flex" justifyContent="flex-end" mb={2}>
        <Button
          variant="contained"
          onClick={() => setCurrentPage("ppi-add-beneficiary")}
          sx={{
            borderRadius: "50px",
            fontWeight: 700,
            px: 4,
            py: 1.2,
            backgroundColor: "#193968",
            color: "#fff",
            "&:hover": { backgroundColor: "#152c56" },
          }}
        >
          + Add Beneficiary
        </Button>
      </Box>

      <Grid container spacing={2}>
        {beneficiaries
          ?.sort((a, b) => {
            if (
              a.bankStatus === "REGISTERED" &&
              b.bankStatus === "UNREGISTERED"
            )
              return -1;
            if (
              a.bankStatus === "UNREGISTERED" &&
              b.bankStatus === "REGISTERED"
            )
              return 1;
            return 0;
          })
          .map((ben) => (
            <Grid key={ben.id} item xs={12} sm={6} md={4} lg={3} xl={2}>
              <Card
                sx={{
                  p: 3,
                  borderRadius: "20px",
                  background:
                    ben.bankStatus === "UNREGISTERED"
                      ? "#f1f3f6"
                      : "linear-gradient(135deg,#ffffff,#f8f9fb)",
                  color: "#193968",
                  position: "relative",
                  boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
                  transition: "0.25s",
                  "&:hover":
                    ben.bankStatus === "REGISTERED"
                      ? { transform: "translateY(-6px)" }
                      : {},
                }}
              >
                {ben.bankStatus === "UNREGISTERED" && (
                  <Typography
                    sx={{
                      position: "absolute",
                      top: 12,
                      right: 12,
                      background: "#cfd6df",
                      color: "#5a7191",
                      fontSize: "11px",
                      fontWeight: 700,
                      px: 1.2,
                      borderRadius: "8px",
                    }}
                  >
                    Deleted
                  </Typography>
                )}

                <Typography fontWeight={700} fontSize={{ xs: 17, sm: 18 }}>
                  {ben.name}
                </Typography>
                <Typography fontSize={15}>Account: {ben.account}</Typography>
                <Typography fontSize={15}>IFSC: {ben.ifsc}</Typography>
                <Typography fontSize={15}>Bank: {ben.bank}</Typography>

                <Box
                  display="flex"
                  justifyContent="space-between"
                  gap={1}
                  mt={2}
                >
                  {/* SEND MONEY BUTTON */}
                  <Button
                    fullWidth
                    variant="contained"
                    disabled={ben.bankStatus === "UNREGISTERED"}
                    onClick={() =>
                      ben.bankStatus === "REGISTERED" && handleOpenPopup(ben)
                    }
                    sx={{
                      borderRadius: "30px",
                      fontWeight: 600,
                      backgroundColor:
                        ben.bankStatus === "UNREGISTERED"
                          ? "#d5d8dd"
                          : "#193968",
                      color: "#fff",
                    }}
                  >
                    Send Money
                  </Button>

                  {/* DELETE BUTTON */}
                  <Button
                    fullWidth
                    variant="outlined"
                    disabled={btnLoading}
                    onClick={() => handleDeleteBeneficiary(ben)}
                    sx={{
                      borderRadius: "30px",
                      fontWeight: 600,
                      borderColor: "#cc9840",
                      color: "#cc9840",
                      "&:hover": {
                        backgroundColor: "#fff6e5",
                      },
                    }}
                  >
                    Delete
                  </Button>
                </Box>
              </Card>
            </Grid>
          ))}
      </Grid>

      {/* SEND MONEY POPUP */}
      <Dialog
        open={openPopup}
        onClose={() => !showOtpField && setOpenPopup(false)}
        fullWidth
        maxWidth="sm"
        fullScreen={isMobile}
        PaperProps={{
          sx: {
            borderRadius: "20px",
            background: "linear-gradient(145deg,#ffffff,#f8faff)",
            width: "100%",
            maxWidth: { xs: "95vw", sm: "580px" },
            overflow: "hidden",
            boxShadow: "0 20px 50px rgba(15, 23, 42, 0.15)",
          },
        }}
      >
        <DialogContent
          sx={{
            p: { xs: 2, sm: 3 },
          }}
        >
          <Box mb={2} textAlign="center">
            <Typography
              fontWeight={700}
              fontSize={{ xs: 18, sm: 20 }}
              color="#193968"
            >
              Send Money
            </Typography>
            <Typography
              fontWeight={500}
              fontSize="13px"
              color="#64748b"
              mt={0.5}
            >
              Verify your identity to continue
            </Typography>
          </Box>

          <Grid container spacing={1.5}>
            {/* BENEFICIARY NAME */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Beneficiary Name"
                value={selectedBen?.name || ""}
                disabled
                sx={disabledInputSx}
              />
            </Grid>

            {/* BANK NAME */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Bank Name"
                value={selectedBen?.bank || ""}
                disabled
                sx={disabledInputSx}
              />
            </Grid>

            {/* ACCOUNT NUMBER */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Account Number"
                value={selectedBen?.account || ""}
                disabled
                sx={disabledInputSx}
              />
            </Grid>

            {/* IFSC */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="IFSC"
                value={selectedBen?.ifsc || ""}
                disabled
                sx={disabledInputSx}
              />
            </Grid>

            {/* MOBILE */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Mobile"
                value={mobile}
                disabled
                sx={disabledInputSx}
              />
            </Grid>

            {/* AMOUNT */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size="small"
                label="Amount"
                className="mui-autofill-fix"
                value={form.transferAmount}
                disabled={showOtpField}
                sx={inputSx}
                onChange={(e) =>
                  setForm({
                    ...form,
                    transferAmount: e.target.value.replace(/\D/g, ""),
                  })
                }
              />
            </Grid>

            {/* TRANSFER MODE (HORIZONTAL RADIOS) */}
            <Grid item xs={12}>
              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  px: 2,
                  py: 0.7,
                  borderRadius: "12px",
                  backgroundColor: "#deecff",
                  border: "1px solid rgba(25, 57, 104, 0.18)",
                }}
              >
                <Typography
                  sx={{
                    fontWeight: 600,
                    fontSize: "13.5px",
                    color: "#193968",
                  }}
                >
                  Transfer Mode:
                </Typography>
                <RadioGroup
                  row
                  name="transferMode"
                  value={form.transferMode}
                  onChange={(e) =>
                    setForm({ ...form, transferMode: e.target.value })
                  }
                  sx={{ display: "flex", gap: { xs: 2, sm: 3 } }}
                >
                  <FormControlLabel
                    value="IMPS"
                    disabled={showOtpField}
                    control={
                      <Radio
                        size="small"
                        sx={{
                          color: "#193968",
                          "&.Mui-checked": { color: "#193968" },
                        }}
                      />
                    }
                    label={
                      <Typography
                        sx={{
                          fontWeight: 600,
                          fontSize: "14px",
                          color: "#193968",
                        }}
                      >
                        IMPS
                      </Typography>
                    }
                    sx={{ mr: 0 }}
                  />
                  <FormControlLabel
                    value="NEFT"
                    disabled={showOtpField}
                    control={
                      <Radio
                        size="small"
                        sx={{
                          color: "#193968",
                          "&.Mui-checked": { color: "#193968" },
                        }}
                      />
                    }
                    label={
                      <Typography
                        sx={{
                          fontWeight: 600,
                          fontSize: "14px",
                          color: "#193968",
                        }}
                      >
                        NEFT
                      </Typography>
                    }
                    sx={{ mr: 0 }}
                  />
                </RadioGroup>
              </Box>
            </Grid>

            {/* OTP */}
            {showOtpField && (
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  size="small"
                  className="mui-autofill-fix"
                  label="Enter OTP"
                  value={form.otp}
                  sx={inputSx}
                  onChange={(e) => setForm({ ...form, otp: e.target.value })}
                />
              </Grid>
            )}

            {/* ACTION BUTTONS */}
            <Grid item xs={12} sx={{ mt: 0.5 }}>
              <Box display="flex" gap={1.5}>
                <Button
                  fullWidth
                  variant="contained"
                  disabled={btnLoading}
                  onClick={!showOtpField ? handleSendOtp : handleConfirmPayment}
                  sx={{
                    py: 1.1,
                    borderRadius: "50px",
                    fontWeight: 700,
                    backgroundColor: "#193968",
                    color: "#fff",
                    fontSize: "14px",
                    "&:hover": { backgroundColor: "#152c56" },
                  }}
                >
                  {btnLoading
                    ? !showOtpField
                      ? "Sending OTP..."
                      : "Processing..."
                    : !showOtpField
                    ? "Send OTP"
                    : "Confirm Payment"}
                </Button>
                <Button
                  variant="outlined"
                  disabled={btnLoading}
                  sx={{
                    minWidth: "110px",
                    borderRadius: "50px",
                    color: "#193968",
                    borderColor: "#cbd5e1",
                    fontWeight: 600,
                    fontSize: "14px",
                    "&:hover": {
                      borderColor: "#94a3b8",
                      backgroundColor: "#f8fafc",
                    },
                  }}
                  onClick={() => setOpenPopup(false)}
                >
                  Cancel
                </Button>
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
      </Dialog>

      {/* DELETE OTP POPUP */}
      <Dialog
        open={openDeletePopup}
        onClose={() => setOpenDeletePopup(false)}
        fullWidth
        maxWidth="xs"
      >
        <DialogContent
          sx={{
            p: { xs: 2.5, sm: 4 },
          }}
        >
          <Typography
            fontWeight={700}
            textAlign="center"
            fontSize={{ xs: 18, sm: 20 }}
            mb={2}
          >
            Enter OTP
          </Typography>

          <TextField
            fullWidth
            className="mui-autofill-fix"
            label="OTP"
            value={deleteOtp}
            inputProps={{ maxLength: 6 }}
            onChange={(e) => setDeleteOtp(e.target.value.replace(/\D/g, ""))}
            sx={inputSx}
          />

          <Button
            fullWidth
            variant="contained"
            disabled={btnLoading}
            onClick={handleDeleteBeneficiaryVerify}
            sx={{
              mt: 3,
              borderRadius: "50px",
              backgroundColor: "#cc9840",
              color: "#fff",
              fontWeight: 700,
            }}
          >
            {btnLoading ? "Deleting..." : "Confirm Delete"}
          </Button>

          <Button
            fullWidth
            sx={{
              mt: 2,
              borderRadius: "50px",
              color: "#193968",
              fontWeight: 600,
            }}
            onClick={() => {
              setDeleteOtp("");
              setOpenDeletePopup(false);
            }}
          >
            Cancel
          </Button>
        </DialogContent>
      </Dialog>

      {/* SAFETY PULL-OUT CONFIRMATION DIALOG */}
      <Dialog
        open={confirmDialogOpen}
        onClose={() => !delinkLoading && setConfirmDialogOpen(false)}
        fullWidth
        maxWidth="xs"
        PaperProps={{
          sx: {
            borderRadius: "20px",
            p: 1.5,
          },
        }}
      >
        <DialogContent sx={{ textAlign: "center", pt: 2, pb: 2 }}>
          <Box
            sx={{
              width: 56,
              height: 56,
              borderRadius: "50%",
              backgroundColor: "#fee2e2",
              color: "#dc2626",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              mx: "auto",
              mb: 2,
            }}
          >
            <WarningAmberIcon sx={{ fontSize: 32 }} />
          </Box>

          <Typography variant="h6" fontWeight={700} color="#1e293b" mb={1}>
            {actionType === "disable"
              ? "De-link & Disable PPI Service?"
              : "De-link Remitter Profile?"}
          </Typography>

          <Typography fontSize={13.5} color="#64748b" mb={3} lineHeight={1.5}>
            {actionType === "disable"
              ? "This will wipe your personal remitter session, remove all saved beneficiaries from BankMudraa, and disable the PPI Bank Transfer service for this account."
              : "This will remove your personal mobile number, session keys, and saved recipient bank accounts from BankMudraa. If anyone logs into this portal, your details will no longer appear."}
          </Typography>

          <Box display="flex" gap={1.5} justifyContent="center">
            <Button
              variant="outlined"
              disabled={delinkLoading}
              onClick={() => setConfirmDialogOpen(false)}
              sx={{
                borderRadius: "30px",
                px: 3,
                textTransform: "none",
                fontWeight: 600,
                color: "#64748b",
                borderColor: "#cbd5e1",
              }}
            >
              Cancel
            </Button>
            <Button
              variant="contained"
              disabled={delinkLoading}
              onClick={handleConfirmDelink}
              sx={{
                borderRadius: "30px",
                px: 3,
                textTransform: "none",
                fontWeight: 700,
                backgroundColor: "#dc2626",
                color: "#fff",
                "&:hover": { backgroundColor: "#b91c1c" },
              }}
            >
              {delinkLoading ? (
                <CircularProgress size={20} sx={{ color: "#fff" }} />
              ) : actionType === "disable" ? (
                "De-link & Disable"
              ) : (
                "Yes, De-link Profile"
              )}
            </Button>
          </Box>
        </DialogContent>
      </Dialog>
    </PpiPageLayout>
  );
};

export default PpiSendMoney;
